package io.github.turbopro.ism.resource.print;import io.github.turbopro.ism.common.api.ApiResponse;import io.github.turbopro.ism.common.infrastructure.authorization.RequiresPermission;import io.github.turbopro.ism.common.infrastructure.web.ApiResponseFactory;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/print-templates")public class PrintController{private final PrintService service;private final ApiResponseFactory responses;public PrintController(PrintService service,ApiResponseFactory responses){this.service=service;this.responses=responses;}@GetMapping @RequiresPermission("print:template:view")ApiResponse<List<PrintModels.TemplateView>>list(){return responses.success(service.templates());}@PostMapping @RequiresPermission("print:template:manage")ApiResponse<PrintModels.TemplateView>create(@Valid@RequestBody PrintModels.SaveTemplate c){return responses.success(service.create(c));}@PutMapping("/{id}")@RequiresPermission("print:template:manage")ApiResponse<PrintModels.TemplateView>update(@PathVariable long id,@Valid@RequestBody PrintModels.SaveTemplate c){return responses.success(service.update(id,c));}@PostMapping("/{id}/publish")@RequiresPermission("print:template:manage")ApiResponse<PrintModels.TemplateView>publish(@PathVariable long id,@RequestParam int version){return responses.success(service.publish(id,version));}@PostMapping("/{id}/preview")@RequiresPermission("print:template:view")ApiResponse<PrintModels.Preview>preview(@PathVariable long id,@RequestBody PrintModels.RenderRequest c){return responses.success(service.preview(id,c));}@PostMapping("/{id}/print")@RequiresPermission("print:execute")ApiResponse<PrintModels.PrintJob>print(@PathVariable long id,@RequestBody PrintModels.RenderRequest c){return responses.success(service.print(id,c));}}
